import type { Bank } from "./types";

const bank: Bank = {
  questions: [
    { id: "audit-001", chapter: "1. Quality Control", prompt: "The board of a listed company approved its financial statements this morning. The engagement partner wants to sign and date the audit report today, but the engagement quality reviewer has not yet finished reviewing the significant judgements. What is the correct course?", options: ["Date the report today and let the reviewer finish within the file-assembly period", "Date the report today but hold back its release until the review is finished", "Not date the auditor's report until the engagement quality review is completed", "Date the report today, since the quality review is an internal firm matter only"], answer: 2, explanation: "The auditor's report cannot be dated until the engagement quality review is complete; holding back release of a report already dated does not cure this." },
    { id: "audit-002", chapter: "1. Quality Control", prompt: "During an audit, the engagement team and the technical partner it consulted disagree on the accounting for a complex financing arrangement. The disagreement is still open on the planned signing date. Which response is appropriate?", options: ["The report should not be finalised until the difference is resolved under the firm's policies", "The engagement partner's view prevails because he signs the auditor's report", "The consulted partner's view prevails because consultation conclusions are binding", "The report may be issued with the dissenting view recorded in the working papers"], answer: 0, explanation: "Firm policies must cover resolving differences of opinion, and the report is not finalised until the matter is resolved; neither party's view wins by default." },
    { id: "audit-003", chapter: "1. Quality Control", prompt: "The final audit file for an engagement was assembled 50 days after the date of the auditor's report. On day 75, an article assistant proposes to remove superseded draft working papers that are still in the file. Under SA 230, this is:", options: ["Permitted, because superseded drafts never form part of the audit documentation", "Not permitted, as nothing may be deleted after assembly until the retention period ends", "Permitted, provided the removal happens within 90 days of the date of the auditor's report", "Not permitted unless the engagement quality reviewer first approves the removal in writing"], answer: 1, explanation: "Once the final file is assembled, SA 230 bars deleting or discarding documentation of any nature before the retention period ends; drafts may be discarded only before assembly is completed." },
    { id: "audit-004", chapter: "1. Quality Control", prompt: "For which of the following engagements do ICAI's quality standards require an engagement quality review in all cases?", options: ["Statutory audit of a private company with turnover above ₹500 crore", "Audit of the financial statements of a listed entity", "Every statutory audit of a company under the Companies Act, 2013", "Tax audit of any assessee whose turnover exceeds ₹10 crore"], answer: 1, explanation: "Audits of listed entities always require an engagement quality review; for other engagements the firm decides using its own criteria." },
    { id: "audit-005", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "Under SA 240, which of the following fraud-risk presumptions or risks can the auditor NOT rebut or treat as absent in any audit?", options: ["Risk of fraud in revenue recognition for a company with a single simple revenue stream", "Risk of material misstatement in inventory valuation due to error", "Risk of misstatement in accounting estimates caused by estimation uncertainty", "Risk of management override of controls"], answer: 3, explanation: "Management override is present in all entities and is always a significant risk; only the revenue recognition fraud presumption can be rebutted, with documented reasons." },
    { id: "audit-006", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "While auditing a company, the statutory auditor finds that employees have committed a fraud involving ₹60 lakh against the company. Under s.143(12) and the related Rules, the auditor should:", options: ["Report to the Central Government in Form ADT-4 within 15 days of receiving the board's reply", "Report to the audit committee or board within 2 days; the Board's report discloses it", "Report it only under the CARO fraud clause, with no other reporting responsibility", "Report directly to the Central Government without first seeking the board's reply"], answer: 1, explanation: "Frauds below ₹1 crore are reported to the audit committee or board within 2 days of the auditor's knowledge and disclosed in the Board's report; only ₹1 crore or more goes to the Central Government." },
    { id: "audit-007", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "An auditor reports a ₹3 crore fraud to the audit committee and seeks its reply. No reply is received within 45 days. What must the auditor do?", options: ["Wait until the next audit committee meeting and then report the fraud to the Central Government", "Drop the matter, because without the committee's reply the report to Government is incomplete", "Forward the report to the Central Government with a note on the earlier report and the missing reply", "Report the fraud only in the Key Audit Matters section of the auditor's report for that year"], answer: 2, explanation: "Under Rule 13, if no reply is received within 45 days, the auditor forwards the report to the Central Government with a note detailing the earlier report for which no reply came." },
    { id: "audit-008", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "A manufacturing company must hold a factory licence and pollution-control consents, which do not directly determine amounts in its financial statements. Under SA 250, the auditor's responsibility for these laws is to:", options: ["Inquire of management and inspect correspondence with licensing authorities to help identify non-compliance", "Obtain sufficient appropriate audit evidence that the company has fully complied with all of them", "Exclude them entirely, as only laws with a direct effect on the financial statements are relevant", "Obtain a legal expert's certificate of full compliance before signing the auditor's report"], answer: 0, explanation: "For laws without a direct effect on the financial statements, SA 250 limits the auditor to inquiry and inspecting regulatory correspondence; full evidence is needed only for direct-effect laws." },
    { id: "audit-009", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "In the proposed terms of an audit engagement that is not required by law, management limits the auditor's access to the records of a major division so that the auditor expects to disclaim an opinion. Under SA 210, the auditor should:", options: ["Accept and issue a qualified opinion limited to that division", "Accept, but include an Emphasis of Matter paragraph on the limitation", "Not accept the limited engagement as an audit engagement", "Accept, provided management confirms the limitation in its written representations"], answer: 2, explanation: "SA 210 bars accepting an engagement as an audit when a limitation imposed by management would lead to a disclaimer, unless law or regulation requires acceptance." },
    { id: "audit-010", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "During an audit, the auditor identifies a significant deficiency in internal control over cash disbursements. Management says it will fix the issue next year, and the auditor explains the deficiency orally to the CFO. Under SA 265, this is:", options: ["Sufficient, because management has agreed to take remedial action in the next year", "Sufficient, provided the conversation with the CFO is recorded in the working papers", "Insufficient, because the deficiency must be reported in the auditor's report as a qualification", "Insufficient, because significant deficiencies must be communicated in writing to TCWG"], answer: 3, explanation: "SA 265 requires significant deficiencies to be communicated in writing to those charged with governance (and to management) in time, whatever remedial action is planned." },
    { id: "audit-011", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "Which of the following companies is NOT required to rotate its auditor under s.139(2) of the Companies Act, 2013?", options: ["Private company with paid-up capital of ₹40 crore and bank borrowings of ₹30 crore", "Unlisted public company with paid-up capital of ₹12 crore and no borrowings", "Private company with paid-up capital of ₹5 crore and bank borrowings of ₹55 crore", "Listed company with paid-up capital of ₹2 crore and no borrowings"], answer: 0, explanation: "Rotation covers listed companies, unlisted public companies with paid-up capital of ₹10 crore or more, private companies with ₹50 crore or more, and any company with public borrowings of ₹50 crore or more." },
    { id: "audit-012", chapter: "2. General Auditing Principles and Auditors Responsibilities", prompt: "CA Rohan, a sole practitioner, is the auditor of Vega Ltd. His brother holds equity shares of Vega Ltd with a face value of ₹80,000 and a market value of ₹3.2 lakh. Is Rohan disqualified under s.141(3)?", options: ["Yes, because the market value of the relative's holding exceeds ₹1 lakh", "Yes, because any holding of securities by a relative disqualifies the auditor", "No, because the relative's holding is within the ₹1 lakh face-value limit", "No, because a brother is not a 'relative' for the purposes of s.141"], answer: 2, explanation: "A relative may hold securities of face value up to ₹1 lakh; the test is face value, not market value. A brother is a relative under the Act." },
    { id: "audit-013", chapter: "3. Audit Planning, Strategy and Execution", prompt: "Which of the following belongs in the audit plan rather than the overall audit strategy under SA 300?", options: ["Identifying the characteristics of the engagement that define its overall scope", "Setting the reporting deadlines and the timing of key communications with TCWG", "Nature, timing and extent of further audit procedures at the assertion level", "Deciding the resources to deploy for specific high-risk areas and their timing"], answer: 2, explanation: "The audit plan is more detailed and covers assertion-level procedures; scope, reporting timelines and resource direction are part of the overall audit strategy." },
    { id: "audit-014", chapter: "5. Audit Evidence", prompt: "In an initial audit engagement, the auditor cannot obtain sufficient appropriate evidence about opening inventory, which is material, because the predecessor did not observe the count and records are unreliable. What is the effect on the current-year report?", options: ["Modify the opinion (qualified or disclaimer, as appropriate), since opening inventory affects current-year profit", "Issue an unmodified opinion with an Other Matter paragraph, as opening balances are the predecessor's responsibility", "Issue an unmodified opinion with an Emphasis of Matter paragraph on opening balances", "Issue an adverse opinion, since opening balances are pervasive by definition"], answer: 0, explanation: "Under SA 510, if sufficient evidence on opening balances cannot be obtained, the auditor modifies the opinion under SA 705; opening inventory directly affects the current year's results." },
    { id: "audit-015", chapter: "3. Audit Planning, Strategy and Execution", prompt: "At which stages of an audit are analytical procedures mandatory?", options: ["Only as substantive procedures for revenue and expense items", "At the planning stage only, as risk assessment procedures", "As substantive procedures and at the final overall review", "In risk assessment and near the end of the audit"], answer: 3, explanation: "SA 315 requires analytical procedures in risk assessment, and SA 520 requires them near the end; using them as substantive procedures is a matter of the auditor's judgement." },
    { id: "audit-016", chapter: "3. Audit Planning, Strategy and Execution", prompt: "Midway through an audit, management asks the auditor to convert the engagement into a review engagement after the auditor insists on sending bank and debtor confirmations that management does not want sent. Under SA 210, the auditor should:", options: ["Agree, since a change to a lower level of assurance is always at the client's option", "Not agree, since a restriction on scope is not a reasonable justification for the change", "Agree, and issue a review report referring to the audit work already done", "Agree, provided the audit fee already agreed is paid in full"], answer: 1, explanation: "A request to change caused by a scope restriction is not reasonable justification; if management will not let the audit continue, the auditor withdraws where possible and considers its obligations." },
    { id: "audit-017", chapter: "3. Audit Planning, Strategy and Execution", prompt: "Which of the following is a preliminary engagement activity that SA 300 requires at the start of the current audit?", options: ["Evaluating compliance with ethical requirements, including independence", "Performing tests of operating effectiveness of key controls", "Sending external confirmations to major customers and suppliers", "Obtaining written representations from management on the accounts"], answer: 0, explanation: "Preliminary activities are continuance procedures, evaluating ethics and independence, and establishing the terms; the other options are later audit procedures." },
    { id: "audit-018", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "Why does an auditor set performance materiality below materiality for the financial statements as a whole?", options: ["To make sure every misstatement, however small, in each account balance is identified and corrected", "To set the threshold below which identified misstatements need not be accumulated by the team", "To keep low the chance that uncorrected and undetected misstatements together exceed materiality", "To set the amount at which a misstatement must be reported to those charged with governance"], answer: 2, explanation: "Performance materiality allows for aggregation risk; the 'clearly trivial' threshold is a separate concept used for accumulating misstatements." },
    { id: "audit-019", chapter: "6. Completion and Review", prompt: "Materiality is ₹40 lakh. An uncorrected misstatement of ₹8 lakh turns a reported loss of ₹5 lakh into a profit of ₹3 lakh. How should the auditor evaluate it?", options: ["It is immaterial, since it is only 20% of materiality", "It may be material for qualitative reasons, since it turns a loss into a profit", "It is automatically pervasive and calls for an adverse opinion", "It can be ignored if management gives a written representation"], answer: 1, explanation: "SA 450 requires considering qualitative factors; a misstatement that turns a loss into a profit can be material even though it is below the quantitative threshold." },
    { id: "audit-020", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "Last year the auditor tested controls over revenue, which has been assessed as a significant risk. The controls have not changed, and the auditor now plans to rely on last year's tests for the current audit. This is:", options: ["Acceptable, provided the auditor confirms through inquiry and observation that nothing has changed", "Acceptable for up to two subsequent audits under the rotation approach", "Acceptable if the engagement partner documents the reasons", "Not acceptable, as controls over a significant risk relied on must be tested in the current period"], answer: 3, explanation: "SA 330 forbids relying on prior-audit evidence for controls that mitigate a significant risk; they must be tested in the current period." },
    { id: "audit-021", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "The auditor responds to a significant risk using only substantive procedures, with no reliance on controls. Under SA 330, those procedures must:", options: ["Include tests of details", "Consist only of substantive analytical procedures", "Be performed entirely at an interim date", "Be limited to external confirmations"], answer: 0, explanation: "When the approach to a significant risk is substantive only, SA 330 requires tests of details; analytical procedures alone are not enough." },
    { id: "audit-022", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "The auditor reassesses the risk of material misstatement for trade receivables from 'moderate' to 'high'. What is the consequence for detection risk and the audit response?", options: ["Acceptable detection risk rises, so fewer substantive procedures are needed", "Detection risk is unaffected, as it depends only on sample size", "Acceptable detection risk falls, so more persuasive substantive evidence is needed", "Inherent risk falls to compensate, so the audit response is unchanged"], answer: 2, explanation: "Detection risk varies inversely with the assessed risk of material misstatement; a higher risk calls for more persuasive evidence, such as larger samples and procedures closer to year end." },
    { id: "audit-023", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "Which statement about the auditor's responsibility under SA 265 is NOT correct?", options: ["The auditor communicates deficiencies identified during the audit", "Significant deficiencies are communicated in writing to those charged with governance", "Other deficiencies of enough importance are communicated to management", "The auditor must design procedures to identify all deficiencies in internal control"], answer: 3, explanation: "The auditor obtains an understanding of internal control only to design audit procedures; SA 265 does not require a search for all deficiencies." },
    { id: "audit-024", chapter: "4. Materiality, Risk Assessment and Internal Control", prompt: "Materiality was set at 1% of expected revenue of ₹500 crore. Mid-audit, a major contract is lost and actual revenue is ₹300 crore. What should the auditor do?", options: ["Revise materiality downward and reconsider performance materiality and procedures", "Keep the original materiality, since it was properly set at the planning stage", "Revise materiality only after the audit fieldwork is completed in full", "Increase performance materiality to make up for the lower revenue figure"], answer: 0, explanation: "SA 320 requires revising materiality when new information would have led to a different amount, and then reconsidering performance materiality and the procedures." },
    { id: "audit-025", chapter: "5. Audit Evidence", prompt: "The CFO refuses to let the auditor send a balance confirmation to the company's largest customer, citing an ongoing commercial dispute. What is the auditor's first required response under SA 505?", options: ["Immediately issue a qualified opinion, citing a limitation on the scope of the audit", "Send the confirmation anyway, since the auditor alone decides who is confirmed", "Inquire into the reasons, test their validity and perform alternative procedures", "Withdraw from the engagement, since the refusal shows management lacks integrity"], answer: 2, explanation: "SA 505 requires inquiring into management's reasons, evaluating them and performing alternative procedures; only if the refusal is unreasonable does the auditor go to TCWG and consider SA 705." },
    { id: "audit-026", chapter: "5. Audit Evidence", prompt: "Receivables are a large population of small, homogeneous balances, the risk of material misstatement is assessed as low with relevant controls tested, and recipients are not expected to ignore requests. The auditor, however, expects about 5% of balances to be in error. May negative confirmations be the sole substantive procedure?", options: ["Yes, since the balances are numerous, small and homogeneous", "Yes, provided the sample size is doubled", "Yes, since controls have been tested and found effective", "No, since a very low expected exception rate is also required"], answer: 3, explanation: "All SA 505 conditions must be met, including a very low expected rate of exceptions; an expected 5% error rate rules out negative confirmations as the sole procedure." },
    { id: "audit-027", chapter: "5. Audit Evidence", prompt: "Floods on the count date prevent the auditor from attending the physical inventory count, which is material. Under SA 501, the auditor should:", options: ["Rely on the client's count sheets and obtain a written representation on quantities", "Count or observe some items on another date and test the intervening transactions", "Qualify the opinion, since attendance on the count date itself was not possible", "Disclaim the opinion, since inventory is material and was not observed at year end"], answer: 1, explanation: "When attendance is prevented by unforeseen circumstances, SA 501 requires counts on an alternative date plus procedures on the transactions in between; modifying the opinion is not the first step." },
    { id: "audit-028", chapter: "5. Audit Evidence", prompt: "Management refuses permission for the auditor to send a letter of inquiry to the company's external legal counsel about a material lawsuit, and no alternative procedure gives sufficient evidence. Under SA 501, the auditor should:", options: ["Modify the opinion in accordance with SA 705", "Issue an unmodified opinion with an Emphasis of Matter paragraph on the litigation", "Rely on management's written representation about the lawsuit", "Report the refusal to the Central Government under s.143(12)"], answer: 0, explanation: "SA 501 requires modifying the opinion when management refuses contact with legal counsel and alternative procedures do not give sufficient appropriate evidence." },
    { id: "audit-029", chapter: "5. Audit Evidence", prompt: "Using ratio estimation, the auditor tests a sample of debtors worth ₹10 lakh from a population of ₹2 crore and finds overstatements of ₹40,000. Tolerable misstatement is ₹6 lakh and overall materiality is ₹25 lakh. What is the projected misstatement, and what is the conclusion?", options: ["₹40,000; acceptable, as it is below tolerable misstatement, so no further work is needed", "₹8,00,000; acceptable, as it is below overall materiality of ₹25 lakh for the audit", "₹8,00,000; it exceeds tolerable misstatement, so further work is needed", "₹4,00,000; acceptable, as it is within tolerable misstatement for the debtors balance"], answer: 2, explanation: "Error rate = 40,000 / 10,00,000 = 4%; projected = 4% × 2,00,00,000 = ₹8,00,000, which exceeds the ₹6 lakh tolerable misstatement, so more work is needed." },
    { id: "audit-030", chapter: "5. Audit Evidence", prompt: "In a sample, the auditor finds one large misstatement and, after obtaining a high degree of certainty, concludes it is an anomaly. How is it treated?", options: ["It is projected to the population in the same way as any other misstatement", "It is ignored entirely, since anomalies are by definition not representative", "It is reported to TCWG as a fraud, and no other evaluation of it is made", "It is excluded from the projection, but its actual amount is still considered"], answer: 3, explanation: "An anomaly is excluded when projecting misstatements, but its actual amount must still be considered alongside the projection of the non-anomalous misstatements." },
    { id: "audit-031", chapter: "5. Audit Evidence", prompt: "Under SA 540, what is the purpose of reviewing the outcome of management's prior-period accounting estimates?", options: ["To call into question judgements made in prior periods", "To help identify and assess risks of material misstatement in the current period", "To decide whether the prior-period financial statements must be restated", "To determine whether the predecessor auditor was negligent"], answer: 1, explanation: "The retrospective review informs current-period risk assessment; it is not meant to question prior judgements made on the information available at the time." },
    { id: "audit-032", chapter: "5. Audit Evidence", prompt: "The auditor discovers a related party that management did not disclose. Which of the following is NOT a required response under SA 550?", options: ["Promptly tell other engagement team members about the related party", "Ask management to identify all transactions with the newly identified related party", "Ask why the entity's controls failed to identify the related party", "Report the non-disclosure to the Central Government as a fraud under s.143(12)"], answer: 3, explanation: "SA 550 requires telling the team, asking management to identify the transactions, asking why controls failed, and performing substantive procedures; non-disclosure alone does not trigger s.143(12)." },
    { id: "audit-033", chapter: "5. Audit Evidence", prompt: "The statutory auditor of a company in India wants members of the company's internal audit department to perform some audit procedures under his direction, supervision and review. Under SA 610 as issued by ICAI, this is:", options: ["Permitted, provided the internal auditors are competent and objective", "Permitted only for procedures involving little judgement", "Permitted if those charged with governance approve it in writing", "Not permitted under ICAI's SA 610 in India"], answer: 3, explanation: "ICAI's SA 610 does not allow internal auditors to provide direct assistance; the external auditor may only use the work of the internal audit function, after evaluating it." },
    { id: "audit-034", chapter: "5. Audit Evidence", prompt: "A company outsources its payroll processing. The user auditor wants to rely on the operating effectiveness of the service organisation's controls. Which report should the user auditor obtain?", options: ["A Type 2 report covering design and operating effectiveness over a period", "A Type 1 report describing the system and control design at a specified date", "A compilation report on the service organisation's financial statements", "An agreed-upon procedures report on the payroll register"], answer: 0, explanation: "A Type 1 report covers only description and design at a date; evidence on operating effectiveness over a period comes from a Type 2 report." },
    { id: "audit-035", chapter: "6. Completion and Review", prompt: "A material uncertainty exists about the entity's ability to continue as a going concern, and the auditor concludes it is adequately disclosed in the financial statements. The auditor's report should contain:", options: ["A qualified opinion, with the uncertainty explained in the Basis for Qualified Opinion section", "An unmodified opinion with an Emphasis of Matter paragraph headed 'Going Concern'", "An unmodified opinion with a separate 'Material Uncertainty Related to Going Concern' section", "A disclaimer of opinion, because the outcome cannot be predicted"], answer: 2, explanation: "Under SA 570 (revised), adequate disclosure means an unmodified opinion plus a separate section headed 'Material Uncertainty Related to Going Concern', not an Emphasis of Matter paragraph." },
    { id: "audit-036", chapter: "6. Completion and Review", prompt: "In the auditor's judgement, the going concern basis is inappropriate because the company has decided to cease operations, but management has prepared the financial statements on a going concern basis. The auditor should express:", options: ["A qualified opinion", "An unmodified opinion with an Emphasis of Matter paragraph", "A disclaimer of opinion", "An adverse opinion"], answer: 3, explanation: "SA 570 requires an adverse opinion when the financial statements are prepared on a going concern basis that the auditor judges inappropriate." },
    { id: "audit-037", chapter: "6. Completion and Review", prompt: "A material uncertainty on going concern exists, but management has not disclosed it adequately in the financial statements. Under SA 570, the auditor should:", options: ["Issue an unmodified opinion and describe the uncertainty as a Key Audit Matter in the report", "Express a qualified or adverse opinion, stating the uncertainty is not adequately disclosed", "Issue an unmodified opinion with a 'Material Uncertainty Related to Going Concern' section", "Disclaim an opinion, since inadequate disclosure of the uncertainty is a scope limitation"], answer: 1, explanation: "Inadequate disclosure of a material uncertainty is a misstatement: qualified or adverse as appropriate, with the basis section saying a material uncertainty exists and is not adequately disclosed." },
    { id: "audit-038", chapter: "6. Completion and Review", prompt: "Management refuses to give the written representation that it has fulfilled its responsibility for preparing the financial statements in accordance with the applicable framework. Under SA 580, the auditor should:", options: ["Disclaim an opinion on the financial statements", "Express a qualified opinion, citing a limitation on scope", "Issue an unmodified opinion, since other evidence is sufficient", "Add an Other Matter paragraph about the refusal"], answer: 0, explanation: "Refusing the representations required by SA 580 on management's responsibilities leads to a disclaimer, since no other evidence can replace them." },
    { id: "audit-039", chapter: "6. Completion and Review", prompt: "After the auditor's report is dated but before the financial statements are issued, management discovers an adjusting event and amends the financial statements, and the board approves the amended version. Under SA 560, the auditor should:", options: ["Issue the original report unchanged, since the audit was already completed on that date", "Add an Other Matter paragraph about the amendment to the original, already dated report", "Withdraw the original report and disclaim an opinion on the amended financial statements", "Extend procedures and issue a new report dated no earlier than the amended approval"], answer: 3, explanation: "SA 560 requires extending procedures to the new report date, and the new report cannot be dated earlier than the approval of the amended financial statements." },
    { id: "audit-040", chapter: "6. Completion and Review", prompt: "Four months after the audited financial statements were issued, the auditor learns that a major debtor had been declared insolvent before the balance sheet date. This fact existed at the report date and would have changed the report. Under SA 560, the auditor should:", options: ["Take no action, since there is no obligation of any kind once the financial statements are issued", "Discuss it with management and TCWG, decide whether amendment is needed and ask how management will address it", "Publicly withdraw the auditor's report without consulting management", "Deal with it only in the next year's auditor's report as an Emphasis of Matter"], answer: 1, explanation: "There is no duty to look for such facts after issue, but if the auditor becomes aware of one, SA 560 requires discussing it, deciding whether amendment is needed and asking how management will respond." },
    { id: "audit-041", chapter: "6. Completion and Review", prompt: "Management refuses to correct several misstatements the auditor has communicated, saying they are immaterial. Which of the following does SA 450 require?", options: ["Treat all of the uncorrected misstatements as material and modify the opinion", "Disclaim an opinion, because management has not cooperated with the auditor", "Understand management's reasons and obtain a written representation on them", "Correct the misstatements in the financial statements without management's consent"], answer: 2, explanation: "SA 450 requires understanding why management will not correct the misstatements and obtaining a written representation that their effects are immaterial, with a summary of them included or attached." },
    { id: "audit-042", chapter: "7. Reporting", prompt: "In the audit of a listed company, the auditor qualifies the opinion because of a material misstatement in revenue recognition, which also took significant auditor attention. How should this matter appear in the report?", options: ["Described in full in the Key Audit Matters section only, with no basis paragraph", "Described in full in both the Basis for Qualified Opinion and Key Audit Matters sections", "Described as an Emphasis of Matter paragraph instead of being a qualification", "Described in the basis for qualified opinion, with a reference to it in the KAM section"], answer: 3, explanation: "Under SA 701, a matter that gives rise to a modified opinion is a KAM by nature but is not described in the KAM section; it is reported under SA 705 and referred to in the KAM section." },
    { id: "audit-043", chapter: "7. Reporting", prompt: "The auditor of a listed company disclaims an opinion because of multiple scope limitations. Unless law or regulation requires otherwise, the report should:", options: ["Include a Key Audit Matters section for the areas that were audited", "Not include a Key Audit Matters section", "Include Key Audit Matters, but only those about the scope limitations", "Include Key Audit Matters, presented as Other Matter paragraphs"], answer: 1, explanation: "SA 705 prohibits a KAM section (and an Other Information section) when the auditor disclaims an opinion, unless law or regulation requires it." },
    { id: "audit-044", chapter: "7. Reporting", prompt: "After year end, a major fire destroys the main plant of an unlisted company. The event is non-adjusting and fully disclosed in a note, and the auditor considers it fundamental to users' understanding. The auditor should:", options: ["Express a qualified opinion because of the uncertainty", "Add an Other Matter paragraph describing the fire", "Add an Emphasis of Matter paragraph referring to the note", "Issue an unmodified opinion with no additional paragraph, since it is disclosed"], answer: 2, explanation: "A matter properly disclosed and fundamental to users' understanding calls for an Emphasis of Matter paragraph under SA 706; the opinion is not modified." },
    { id: "audit-045", chapter: "7. Reporting", prompt: "An auditor issues a report on financial statements prepared for submission to a lender and wishes to state that the report is intended solely for that lender and should not be distributed to others. Where should this appear?", options: ["In the Basis for Opinion section as a qualification", "In an Emphasis of Matter paragraph", "In the Key Audit Matters section", "In an Other Matter paragraph"], answer: 3, explanation: "A restriction on distribution or use concerns a matter not presented in the financial statements, so it belongs in an Other Matter paragraph under SA 706." },
    { id: "audit-046", chapter: "7. Reporting", prompt: "A parent company has not consolidated a large subsidiary, contrary to the applicable framework. The effects on the consolidated financial statements are material and pervasive but cannot be quantified practicably. The auditor should express:", options: ["An adverse opinion", "A qualified opinion", "A disclaimer of opinion", "An unmodified opinion with an Emphasis of Matter paragraph"], answer: 0, explanation: "This is a misstatement (not a lack of evidence) that is material and pervasive, so SA 705 requires an adverse opinion even if the effects cannot be quantified." },
    { id: "audit-047", chapter: "7. Reporting", prompt: "The auditor cannot obtain sufficient appropriate evidence about the carrying amount of an investment in an overseas associate. The possible effects are material but not pervasive. The auditor should express:", options: ["An adverse opinion", "A qualified opinion stating 'except for the possible effects' of the matter", "A disclaimer of opinion", "A qualified opinion stating 'except for the effects' of the misstatement"], answer: 1, explanation: "An inability to obtain evidence whose possible effects are material but not pervasive leads to a qualified opinion worded as 'except for the possible effects'." },
    { id: "audit-048", chapter: "7. Reporting", prompt: "Last year's opinion was qualified for non-provision of a material doubtful receivable. The matter is unresolved and is material to both the current-year and the corresponding figures. Under SA 710, the current-year opinion should be:", options: ["Unmodified, since the qualification already appeared in last year's auditor's report", "Unmodified, with an Other Matter paragraph mentioning last year's qualification", "Modified for the corresponding figures only, with the current period unaffected", "Modified, with the basis section referring to both current and corresponding figures"], answer: 3, explanation: "Under SA 710, an unresolved matter material to both periods leads to a modified current opinion, with the basis section referring to both the current and corresponding figures." },
    { id: "audit-049", chapter: "7. Reporting", prompt: "The prior-period financial statements of a company were not audited. In the current-year audit report, SA 710 requires the auditor to:", options: ["State in an Other Matter paragraph that the corresponding figures are unaudited, while still obtaining evidence on opening balances", "Qualify the opinion, since the corresponding figures are unaudited", "State in an Other Matter paragraph that the corresponding figures are unaudited, which removes the need to test opening balances", "Include an Emphasis of Matter paragraph saying the corresponding figures are unaudited"], answer: 0, explanation: "SA 710 requires an Other Matter paragraph stating the figures are unaudited; this does not remove the need for sufficient evidence that opening balances are not materially misstated." },
    { id: "audit-050", chapter: "7. Reporting", prompt: "Before the report date, the auditor reads the directors' report (other information) and finds a material misstatement that management refuses to correct. The financial statements themselves are fairly stated. Under SA 720, the auditor should:", options: ["Express a qualified opinion on the financial statements because of the misstatement", "Issue an adverse opinion, since the annual report as a whole is misleading", "Describe it in the Other Information section, without modifying the opinion", "Ignore it, since other information is outside the scope of the audit altogether"], answer: 2, explanation: "A misstatement in the other information does not modify the opinion on fairly stated financial statements; SA 720 requires describing it in the Other Information section, after informing TCWG." },
    { id: "audit-051", chapter: "7. Reporting", prompt: "A private company (not a holding or subsidiary of a public company) has paid-up capital plus reserves of ₹90 lakh on the balance sheet date and revenue of ₹8 crore. Its bank borrowings peaked at ₹1.2 crore in October and were ₹40 lakh at year end. Does CARO 2020 apply?", options: ["No, since year-end borrowings are below ₹1 crore", "No, since revenue is below ₹10 crore and net worth is below ₹1 crore", "Yes, since revenue exceeds ₹5 crore", "Yes, since borrowings exceeded ₹1 crore at a point during the year"], answer: 3, explanation: "The private-company exemption requires borrowings not exceeding ₹1 crore at any point during the year; the October peak of ₹1.2 crore means CARO applies." },
    { id: "audit-052", chapter: "7. Reporting", prompt: "During the year, a company had working capital limits of ₹4 crore from Bank A and ₹2 crore from Bank B, both secured by current assets. Which CARO 2020 reporting requirement does this trigger?", options: ["Whether the quarterly returns filed with the banks agree with the books", "None, since neither bank's limit exceeds ₹5 crore when taken on its own", "Only whether the company has defaulted on repayment of dues to the banks", "Whether the limits were approved by a special resolution of the members"], answer: 0, explanation: "Clause 3(ii)(b) applies when working capital limits secured by current assets exceed ₹5 crore in aggregate; 4 + 2 = ₹6 crore, so agreement of quarterly returns with the books is reported." },
    { id: "audit-053", chapter: "7. Reporting", prompt: "An unlisted public company has turnover of ₹10 crore and no borrowings. Must its statutory auditor report on the adequacy and operating effectiveness of internal financial controls with reference to financial statements under s.143(3)(i)?", options: ["No, since its turnover is below ₹50 crore", "No, since it has no borrowings from banks or financial institutions", "Yes, since the exemption is available only to certain private companies", "Yes, but only if the company is a subsidiary of a listed company"], answer: 2, explanation: "The s.143(3)(i) exemption by turnover or borrowing thresholds is available only to private companies (and OPCs and small companies); every public company is covered." },
    { id: "audit-054", chapter: "7. Reporting", prompt: "The auditor finds that the edit-log (audit trail) feature of the company's accounting software was switched off for two months of the year. How does this affect the auditor's reporting under the Companies (Audit and Auditors) Rules, 2014?", options: ["No reporting is needed if the books of account are otherwise correct and complete", "It is reported only in the CARO report, under the clause on fraud noticed or reported", "It must be reported to the Central Government in Form ADT-4 within the prescribed time", "It is reported under Rule 11(g), as the audit trail did not operate throughout the year"], answer: 3, explanation: "Rule 11(g) requires the auditor to report whether accounting software with an audit trail feature was used and whether it operated throughout the year for all transactions and was not tampered with." },
    { id: "audit-055", chapter: "8. Specialised Areas", prompt: "An auditor reports under SA 800 on financial statements prepared using a tax-basis special purpose framework. Which element must the report include?", options: ["A Key Audit Matters section covering the basis of preparation and the tax framework", "An Emphasis of Matter paragraph alerting users to the special purpose framework", "An adverse opinion on fair presentation, since Ind AS has not been followed", "A statement that the financial statements comply with Schedule III to the Act"], answer: 1, explanation: "SA 800 requires an Emphasis of Matter paragraph stating that the financial statements use a special purpose framework and may not be suitable for another purpose." },
    { id: "audit-056", chapter: "8. Specialised Areas", prompt: "The auditor has expressed an adverse opinion on a company's complete set of financial statements. The company now asks the same auditor for an unmodified opinion on its balance sheet alone, in a separate report. Under SA 805:", options: ["This is permitted, provided the report is not published with the adverse report", "This is permitted if the balance sheet is free from the misstatements behind the adverse opinion", "This is not permitted, since a single financial statement of the complete set is a major portion of it", "This is permitted with an Emphasis of Matter paragraph referring to the adverse opinion"], answer: 2, explanation: "SA 805 bars an unmodified opinion on a single financial statement from a complete set that got an adverse opinion or disclaimer, even in a separate report, since it is a major portion of the set." },
    { id: "audit-057", chapter: "8. Specialised Areas", prompt: "The auditor's report on a company's audited financial statements contains a disclaimer of opinion. The company asks for a report on the summary financial statements derived from them. Under SA 810, the auditor's report on the summary financial statements should:", options: ["State that it is inappropriate to express an opinion on the summary financial statements", "Express an unmodified opinion that the summary is consistent with the audited statements", "Express a qualified opinion on the summary financial statements", "Express an adverse opinion on the summary financial statements"], answer: 0, explanation: "When the report on the audited financial statements is adverse or a disclaimer, SA 810 requires stating that it is inappropriate to express an opinion on the summary financial statements." },
    { id: "audit-058", chapter: "9. Related Services", prompt: "A bank asks a CA to carry out agreed-upon procedures on a borrower's stock statements under SRS 4400. Which statement about the output is correct?", options: ["The CA gives limited assurance in negative form on the stock statements as a whole", "The CA gives reasonable assurance on the stock statements as a whole to the bank", "The CA reports factual findings, gives no assurance and restricts the report's use", "The CA issues a compilation report signed by the borrower's management as well"], answer: 2, explanation: "In an SRS 4400 engagement the user draws conclusions from a report of factual findings; no assurance is given and the report is restricted to the parties that agreed the procedures." },
    { id: "audit-059", chapter: "9. Related Services", prompt: "A CA who is not independent of a company is asked to carry out an agreed-upon procedures engagement under SRS 4400, and the terms of engagement do not require independence. Which is correct?", options: ["The CA must decline, since independence is required for all ICAI engagements", "The CA may accept, and the report states that the CA is not independent", "The CA may accept, and need not mention independence anywhere in the report", "The CA may accept only if the engagement is converted into a review engagement"], answer: 1, explanation: "Independence is not a requirement for SRS 4400 engagements unless the terms or law require it; if the practitioner is not independent, the report says so." },
    { id: "audit-060", chapter: "9. Related Services", prompt: "While compiling financial information under SRS 4410, the accountant finds that it is materially misstated and management refuses to make the amendments he proposes. The accountant should:", options: ["Issue the compilation report with a qualified conclusion", "Issue the compilation report, since no assurance is given in any case", "Report the matter to the Central Government", "Withdraw from the engagement"], answer: 3, explanation: "In a compilation, the accountant proposes amendments; if management declines to correct materially misstated or misleading information, he withdraws rather than be associated with it." },
    { id: "audit-061", chapter: "10. Review of Financial Information", prompt: "In a limited review of a listed company's quarterly results under SRE 2410, which procedure would ordinarily NOT be performed?", options: ["Inquiries of members of management responsible for financial and accounting matters", "Analytical procedures on the interim financial information", "Sending external confirmations to debtors and testing controls over sales", "Reading the minutes of shareholder and board meetings"], answer: 2, explanation: "A review consists mainly of inquiry and analytical procedures; SRE 2410 does not ordinarily require confirmation, inspection or tests of controls." },
    { id: "audit-062", chapter: "10. Review of Financial Information", prompt: "In an SRE 2410 review, the auditor concludes that a material uncertainty on going concern exists and is adequately disclosed in the interim financial information. The review report should:", options: ["Express a qualified conclusion, citing the going concern uncertainty", "Express an adverse conclusion on the interim financial information", "State that no conclusion can be expressed on the interim information", "Add an Emphasis of Matter paragraph, with the conclusion unmodified"], answer: 3, explanation: "Under SRE 2410, adequately disclosed going concern uncertainty calls for an Emphasis of Matter paragraph; inadequate disclosure would lead to a qualified or adverse conclusion." },
    { id: "audit-063", chapter: "10. Review of Financial Information", prompt: "What is the key difference between an engagement under SRE 2400 and one under SRE 2410?", options: ["SRE 2400 is used by a practitioner who is not the auditor; SRE 2410 by the auditor", "SRE 2400 gives reasonable assurance, while SRE 2410 gives only limited assurance", "SRE 2400 applies only to interim information; SRE 2410 only to annual statements", "SRE 2400 requires tests of controls, while SRE 2410 requires inquiry only"], answer: 0, explanation: "Both give limited assurance; SRE 2410 covers review of interim information by the entity's auditor, while SRE 2400 is used by a practitioner who is not the auditor." },
    { id: "audit-064", chapter: "11. Prospective Financial Information and Other Assurance Services", prompt: "A start-up prepares projected financial statements assuming it obtains a licence that has not yet been applied for and a plant that may or may not be built. Under SAE 3400, this information is:", options: ["A forecast, since it is based on management's best estimates", "A pro forma statement, since it shows the effect of a hypothetical event", "A projection, since it rests on hypothetical assumptions about future events", "A budget, which falls outside SAE 3400"], answer: 2, explanation: "A forecast uses best-estimate assumptions; prospective information based on hypothetical assumptions about events that may not occur is a projection." },
    { id: "audit-065", chapter: "11. Prospective Financial Information and Other Assurance Services", prompt: "In a report under SAE 3400 on a profit forecast, the assurance given on management's assumptions is:", options: ["Negative assurance: nothing suggests the assumptions are not a reasonable basis", "Reasonable assurance that the forecast results will actually be achieved", "A positive opinion that the assumptions used are correct and complete", "No assurance, since the report is one of factual findings only"], answer: 0, explanation: "SAE 3400 gives negative assurance on the assumptions and an opinion on proper preparation and presentation, with a caveat that actual results are likely to differ." },
    { id: "audit-066", chapter: "11. Prospective Financial Information and Other Assurance Services", prompt: "A payroll service organisation uses a separate data-centre company for hosting. Its SAE 3402 Type 2 report describes only its own controls and excludes the data centre's control objectives and controls from the description and the scope of the engagement. This presentation is called:", options: ["The inclusive method", "A Type 1 presentation", "The complementary user entity controls method", "The carve-out method"], answer: 3, explanation: "Excluding a subservice organisation's controls from the description and scope is the carve-out method; the inclusive method brings them within the description and scope." },
    { id: "audit-067", chapter: "11. Prospective Financial Information and Other Assurance Services", prompt: "In an SAE 3420 engagement on pro forma financial information included in a prospectus, the practitioner's opinion addresses:", options: ["Whether the acquisition would actually have produced the results shown in it", "Whether the pro forma information has been properly compiled on the applicable criteria", "Whether the source historical financial information gives a true and fair view", "Whether the pro forma adjustments will actually be achieved in future periods"], answer: 1, explanation: "Under SAE 3420 the practitioner reports on whether the responsible party properly compiled the pro forma information; there is no opinion on actual outcomes or a fresh audit of the source data." },
    { id: "audit-068", chapter: "12. Digital Auditing & Assurance", prompt: "The auditor finds that IT general controls over program changes at a client were ineffective for most of the year. What is the main effect on the audit of automated application controls?", options: ["None, since automated controls run consistently whatever the state of change controls", "Reliance on them needs further testing, and more substantive work may be needed", "The auditor must issue a disclaimer of opinion because the IT environment is unreliable", "The auditor needs only a management representation that no program changes were made"], answer: 1, explanation: "Ineffective change management undermines the consistent operation of automated controls, so reliance needs more testing or more substantive work." },
    { id: "audit-069", chapter: "12. Digital Auditing & Assurance", prompt: "Which CAAT involves running dummy transactions through the client's live or copied application to check whether its programmed controls and logic work as intended?", options: ["Generalised audit software extracting exceptions from master files", "Embedded audit module collecting data continuously", "Data analytics stratifying the full population", "Test data technique"], answer: 3, explanation: "The test data technique processes auditor-designed dummy transactions to test program logic; generalised audit software analyses the client's actual data." },
    { id: "audit-070", chapter: "12. Digital Auditing & Assurance", prompt: "Which statement about using data analytics to test 100% of a population is NOT correct?", options: ["Testing the whole population gives the auditor absolute assurance", "The completeness and accuracy of the data extracted must be verified", "Exceptions identified must be followed up with further procedures", "Professional judgement is still needed to set the parameters and assess the results"], answer: 0, explanation: "Analytics reduce sampling risk but cannot give absolute assurance; data reliability, judgement and inherent limitations remain." },
    { id: "audit-071", chapter: "12. Digital Auditing & Assurance", prompt: "IT general controls are effective and an automated three-way-match control has not changed since the auditor tested it. Why may limited testing of the automated control (benchmarking) be enough?", options: ["Because automated controls are never subject to management override of any kind", "Because SA 330 exempts automated controls from tests of operating effectiveness", "Because an automated control performs consistently unless its program is changed", "Because the client's IT department certifies the control as unchanged each year"], answer: 2, explanation: "With effective change controls, an automated control keeps operating the same way, so evidence from earlier testing combined with ITGC evidence can support reliance." },
    { id: "audit-072", chapter: "13. Group Audits", prompt: "Which paragraph of CARO 2020 applies to the auditor's report on consolidated financial statements?", options: ["All of paragraph 3 applies in full to the consolidated financial statements", "Only the clauses on fixed assets and on inventory apply to the consolidated statements", "CARO does not apply in any way to the report on consolidated financial statements", "Only clause 3(xxi), on adverse remarks in the components' own CARO reports"], answer: 3, explanation: "CARO 2020 applies to consolidated statements only through clause 3(xxi), which lists the companies and clauses with qualifications or adverse remarks in their own CARO reports." },
    { id: "audit-073", chapter: "13. Group Audits", prompt: "A parent's group includes an Indian subsidiary, an Indian associate and a foreign subsidiary. In reporting on internal financial controls under s.143(3)(i) for the consolidated financial statements, the auditor's report covers:", options: ["The parent and its subsidiaries, associates and joint ventures incorporated in India", "The parent company only, since IFC is reported entity by entity", "Every group entity, including the foreign subsidiary and the associate", "The parent and its subsidiaries only, excluding associates and joint ventures"], answer: 0, explanation: "IFC reporting on consolidated statements covers the parent and its subsidiaries, associates and joint ventures that are companies incorporated in India; foreign components are excluded." },
    { id: "audit-074", chapter: "13. Group Audits", prompt: "A subsidiary's reporting date is 31 December, while the parent's is 31 March. The group uses the subsidiary's 31 December statements without preparing additional ones. What must the group auditor check under Ind AS 110?", options: ["Nothing, since any difference in reporting dates is acceptable under Ind AS 110", "That the subsidiary prepared statements up to 31 March, since no difference is allowed", "That the gap is no more than three months, with adjustments for significant events", "That the gap is no more than six months and the subsidiary is not material to the group"], answer: 2, explanation: "Ind AS 110 allows the subsidiary's latest statements if the difference is no more than three months, adjusted for significant transactions or events in between." },
    { id: "audit-075", chapter: "13. Group Audits", prompt: "A parent sold goods to its subsidiary for ₹50 lakh at cost plus 25%. At year end, 40% of these goods are still in the subsidiary's inventory. What unrealised profit should the group auditor expect to be eliminated on consolidation?", options: ["₹5 lakh", "₹12.5 lakh", "₹10 lakh", "₹4 lakh"], answer: 3, explanation: "Unsold stock at transfer price = 50 × 40% = ₹20 lakh; profit element = 20 × 25/125 = ₹4 lakh (not 25% of ₹20 lakh, which wrongly applies the markup to selling price)." },
    { id: "audit-076", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "A bank gives a farmer a crop loan for a short-duration crop. When does it become a non-performing asset?", options: ["When an instalment of principal or interest stays overdue for one crop season", "When an instalment stays overdue for more than 90 days", "When an instalment of principal or interest stays overdue for two crop seasons", "When an instalment stays overdue for more than 180 days"], answer: 2, explanation: "Short-duration crop loans become NPAs when overdue for two crop seasons; long-duration crop loans after one crop season." },
    { id: "audit-077", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "A borrower has a term loan and a cash credit facility with the same bank. The term loan becomes an NPA, but the cash credit account is running regularly. How should the bank classify the cash credit account?", options: ["As an NPA, since classification is borrower-wise, not facility-wise", "As standard, since the cash credit account is operated regularly", "As a special mention account, pending a review of the borrower", "As standard, if it is fully secured by stock and book debts"], answer: 0, explanation: "Under RBI's prudential norms, classification is borrower-wise, so all facilities of a borrower are NPAs once one of them is." },
    { id: "audit-078", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "A borrower whose loan was classified as an NPA pays all overdue interest but not the overdue principal instalments. Under RBI's current norms, can the account be upgraded to standard?", options: ["Yes, since payment of all the interest arrears is enough for an upgrade", "Yes, if the bank's credit committee approves the upgrade on review", "Yes, after the borrower has repaid half of the principal arrears as well", "No, since all arrears of both interest and principal must be paid"], answer: 3, explanation: "RBI's November 2021 clarification allows upgrading an NPA to standard only when all arrears of interest and principal are paid." },
    { id: "audit-079", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "A loan becomes an NPA during the year. Interest of ₹3 lakh was accrued and credited to income in earlier periods but has not been realised. What should the auditor expect?", options: ["The interest stays in income, since it was properly accrued when credited", "The unrealised interest previously credited to income is reversed", "The interest stays in income but a 100% provision is made against the loan", "The interest is moved to capital reserve"], answer: 1, explanation: "When an advance becomes an NPA, interest accrued and credited to income in past periods that is unrealised must be reversed; NPA income is recognised only on realisation." },
    { id: "audit-080", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "A term loan (not a revolving facility) has an instalment overdue for 45 days. Under RBI's early-stress framework, it is classified as:", options: ["SMA-0", "SMA-2", "SMA-1", "NPA"], answer: 2, explanation: "For non-revolving loans: SMA-0 is up to 30 days, SMA-1 more than 30 and up to 60 days, and SMA-2 more than 60 and up to 90 days overdue." },
    { id: "audit-081", chapter: "14. Special Features of Audit of Banks & Non-Banking Financial Companies", prompt: "At year end, a company's financial assets are 55% of its total assets, and income from financial assets is 45% of its gross income. Under RBI's principal business test, is it treated as an NBFC?", options: ["Yes, since its financial assets exceed 50% of its total assets", "Yes, since either of the two conditions alone is enough", "No, since financial assets must exceed 75% of total assets", "No, since both conditions must be met and the income test fails"], answer: 3, explanation: "The 50-50 test needs both: financial assets over 50% of total assets and financial income over 50% of gross income." },
    { id: "audit-082", chapter: "15. Overview of Audit of Public Sector Undertakings", prompt: "Within what period from the start of a financial year must the C&AG appoint the statutory auditor of an existing government company under s.139(5)?", options: ["60 days", "180 days", "30 days", "90 days"], answer: 1, explanation: "Under s.139(5), the C&AG appoints the auditor of a government company within 180 days from the commencement of the financial year." },
    { id: "audit-083", chapter: "15. Overview of Audit of Public Sector Undertakings", prompt: "After receiving the statutory auditor's report on a government company, the C&AG may conduct a supplementary audit under s.143(6). Within what period?", options: ["Within 60 days from receipt of the audit report", "Within 180 days from the end of the financial year", "At any time before the annual general meeting", "Within 30 days from adoption of the accounts"], answer: 0, explanation: "Under s.143(6)(a), the C&AG may conduct a supplementary audit within 60 days of receiving the audit report and may comment on or supplement it." },
    { id: "audit-084", chapter: "15. Overview of Audit of Public Sector Undertakings", prompt: "A new government company is registered, but the C&AG does not appoint its first auditor within the prescribed time. Who appoints the first auditor next?", options: ["The members at the first annual general meeting", "The Central Government, through the Regional Director", "The Board of Directors, within the next 30 days", "The audit committee, at its first meeting"], answer: 2, explanation: "Under s.139(7), the C&AG appoints within 60 days of registration; failing that, the Board within the next 30 days; failing that, members at an EGM within 60 days." },
    { id: "audit-085", chapter: "15. Overview of Audit of Public Sector Undertakings", prompt: "While auditing a public sector undertaking, an auditor examines whether lavish hospitality spending, though properly authorised and recorded, was more than the occasion demanded. This is an example of:", options: ["Performance audit of economy, efficiency and effectiveness", "Compliance audit of the sanction process", "Financial attest audit", "Propriety audit"], answer: 3, explanation: "Propriety audit tests spending against canons of financial propriety, such as not spending more than the occasion demands, beyond mere authorisation." },
    { id: "audit-086", chapter: "16. Internal Audit", prompt: "In the preceding financial year, an unlisted public company had paid-up capital of ₹30 crore, turnover of ₹150 crore, peak bank borrowings of ₹90 crore and peak public deposits of ₹20 crore. Must it appoint an internal auditor under s.138?", options: ["No, since none of the prescribed thresholds was reached", "Yes, since its turnover exceeds the ₹100 crore threshold", "Yes, since its bank borrowings exceed the ₹50 crore threshold", "Yes, since it has accepted deposits from the public"], answer: 0, explanation: "Unlisted public companies need internal audit at paid-up capital ₹50 crore, turnover ₹200 crore, borrowings ₹100 crore or deposits ₹25 crore; none was reached." },
    { id: "audit-087", chapter: "16. Internal Audit", prompt: "The statutory auditor of a company is asked to also carry out the internal audit of its wholly owned subsidiary. Under s.144 of the Companies Act, 2013:", options: ["It is allowed, since the internal audit is of a different legal entity", "It is allowed with the prior approval of the company's audit committee", "It is not allowed, since the bar extends to holding and subsidiary companies", "It is allowed if the internal audit is done by a different partner of the firm"], answer: 2, explanation: "Section 144 bars the auditor from providing internal audit, directly or indirectly, to the company or its holding or subsidiary company; approvals do not override it." },
    { id: "audit-088", chapter: "16. Internal Audit", prompt: "The head of a company's internal audit function reports to the CFO, who also sets his remuneration, and internal audit findings on the finance function are often removed from reports. Under SA 610, the external auditor should:", options: ["Use the function's work, since the internal auditors are competent CAs", "Use the function's work, but only for areas assessed as low risk", "Use the work after obtaining a written representation from the CFO", "Not use the function's work, since its objectivity is not supported"], answer: 3, explanation: "SA 610 forbids using the internal audit function's work when its status and policies do not adequately support objectivity, however competent its staff." },
    { id: "audit-089", chapter: "16. Internal Audit", prompt: "Which feature best distinguishes risk-based internal audit from a traditional transaction-based internal audit?", options: ["It checks every transaction in the period for arithmetical accuracy", "It ranks auditable areas by risk and focuses on the highest-risk ones", "It is performed only after the statutory audit has been completed", "It takes over management's responsibility for internal control"], answer: 1, explanation: "Risk-based internal audit ranks auditable units by assessed risk and puts more effort on high-risk areas, instead of uniform transaction checking." },
    { id: "audit-090", chapter: "17. Due Diligence, Investigation & Forensic Accounting", prompt: "In a financial due diligence, the target's reported net worth is ₹20 crore. Findings: unrecorded gratuity liability ₹1.50 crore; inventory overvalued by ₹0.80 crore; a guarantee likely to be invoked of ₹0.50 crore; and a disputed claim of ₹2 crore whose chance of success is remote. What is the adjusted net worth?", options: ["₹15.20 crore", "₹17.70 crore", "₹17.20 crore", "₹18.70 crore"], answer: 2, explanation: "20 − 1.50 − 0.80 − 0.50 = ₹17.20 crore; the remote claim is not adjusted (deducting it gives the ₹15.20 crore distractor)." },
    { id: "audit-091", chapter: "17. Due Diligence, Investigation & Forensic Accounting", prompt: "Which statement about investigation, as compared with audit, is NOT correct?", options: ["An investigation is always confined to a single financial year", "An investigation is carried out for a specific purpose defined by the person commissioning it", "An investigation may go into records of several past years as the purpose needs", "An investigation does not necessarily end in an opinion on true and fair view"], answer: 0, explanation: "An investigation's period depends on its objective and may cover many years; it is fact-finding and need not give a true-and-fair opinion." },
    { id: "audit-092", chapter: "17. Due Diligence, Investigation & Forensic Accounting", prompt: "In a forensic investigation, the investigator takes a forensic image of a suspect's laptop. Which step best preserves the evidential value of the image?", options: ["Opening the original files to check that they are relevant", "Storing the image on a shared drive open to the whole team", "Copying only the files that look relevant and discarding the rest", "Recording a hash value and keeping a documented chain of custody"], answer: 3, explanation: "Hash values prove the image matches the original and has not been altered; a documented chain of custody shows who handled the evidence and when." },
    { id: "audit-093", chapter: "17. Due Diligence, Investigation & Forensic Accounting", prompt: "Under Benford's law, roughly what share of naturally occurring numbers in a large set of transaction amounts would be expected to start with the digit 1?", options: ["About 11%", "About 30%", "About 50%", "About 18%"], answer: 1, explanation: "Benford's law predicts a leading 1 about 30.1% of the time (log10 2); a uniform 11% share of each digit can signal fabricated figures." },
    { id: "audit-094", chapter: "18. Sustainable Development Goals (SDG) & Environment, Social and Governance (ESG) Assurance", prompt: "A company runs diesel generators that it owns at its factory and also buys electricity from the state grid. How are the emissions from the diesel generators classified?", options: ["Scope 1, as direct emissions from sources it owns or controls", "Scope 2, as indirect emissions from the energy it consumes", "Scope 3, as indirect emissions from its value chain", "Scope 2, because the generators are used to produce electricity"], answer: 0, explanation: "Burning fuel in owned equipment gives direct (Scope 1) emissions; purchased grid electricity gives indirect Scope 2 emissions." },
    { id: "audit-095", chapter: "18. Sustainable Development Goals (SDG) & Environment, Social and Governance (ESG) Assurance", prompt: "How does a limited assurance conclusion on a sustainability report generally differ from a reasonable assurance conclusion?", options: ["Limited assurance is a positive-form opinion that the information is fairly stated", "Limited assurance needs more extensive procedures than a reasonable assurance one", "Limited assurance is a report of factual findings, with no conclusion expressed", "Limited assurance is worded negatively: nothing has come to the practitioner's attention"], answer: 3, explanation: "Limited assurance uses fewer procedures and a negatively worded conclusion; reasonable assurance gives a positive-form opinion." },
    { id: "audit-096", chapter: "18. Sustainable Development Goals (SDG) & Environment, Social and Governance (ESG) Assurance", prompt: "Under SEBI's LODR Regulations, the Business Responsibility and Sustainability Report (BRSR) is mandatory for:", options: ["All listed entities, whatever their size", "The top 1,000 listed entities by market capitalisation", "All unlisted public companies with net worth above ₹500 crore", "Only the top 100 listed entities by market capitalisation"], answer: 1, explanation: "SEBI requires the top 1,000 listed entities by market capitalisation to include a BRSR in their annual report; others may file voluntarily." },
    { id: "audit-097", chapter: "18. Sustainable Development Goals (SDG) & Environment, Social and Governance (ESG) Assurance", prompt: "In ESG reporting, the 'double materiality' approach requires an entity to assess:", options: ["Materiality twice, once at the planning stage and again at the completion stage", "Only the financial effect of sustainability matters on the entity's enterprise value", "Both its impact on people and the planet and the financial effect of ESG matters on it", "Materiality at twice the level used for the audit of the financial statements"], answer: 2, explanation: "Double materiality combines impact materiality (outward effect on society and the environment) and financial materiality (inward effect on enterprise value)." },
    { id: "audit-098", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "CA Arjun accepts appointment as statutory auditor of a company in place of CA Bela. He only spoke to Bela on the telephone before accepting and sent nothing in writing. Arjun is guilty of professional misconduct under:", options: ["Clause (9) of Part I of the First Schedule", "Clause (1) of Part I of the Second Schedule", "Clause (2) of Part IV of the First Schedule", "Clause (8) of Part I of the First Schedule"], answer: 3, explanation: "Clause (8) of Part I of the First Schedule requires first communicating in writing with the previous auditor; a phone call is not enough." },
    { id: "audit-099", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA accepts appointment as auditor of a company without first checking whether the company has complied with s.139 and s.140 of the Companies Act, 2013 for the appointment. This is misconduct under:", options: ["Clause (9) of Part I of the First Schedule", "Clause (8) of Part I of the First Schedule", "Clause (7) of Part I of the Second Schedule", "Clause (10) of Part I of the First Schedule"], answer: 0, explanation: "Clause (9) of Part I of the First Schedule covers accepting a company audit without first checking that the statutory appointment requirements were complied with." },
    { id: "audit-100", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA in practice, appointed as liquidator of a company, charges fees at a percentage of the amounts realised from assets. Is this professional misconduct?", options: ["Yes, under clause (10) of Part I of the First Schedule, since fees are a percentage", "Yes, under clause (2) of Part I of the First Schedule, since it is a share of realisations", "No, since fees of a liquidator or receiver may be based on a percentage of realisation", "No, since the bar on percentage fees applies only to audit engagements"], answer: 2, explanation: "Clause (10) bars percentage or contingent fees, but the regulations permit percentage-based fees for liquidators and receivers; the bar is not limited to audits." },
    { id: "audit-101", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA expresses an audit opinion on the financial statements of a firm in which his own partner has a substantial interest. This is misconduct under:", options: ["Clause (11) of Part I of the First Schedule", "Clause (4) of Part I of the Second Schedule", "Clause (5) of Part I of the Second Schedule", "Clause (1) of Part II of the Second Schedule"], answer: 1, explanation: "Clause (4) of Part I of the Second Schedule bars expressing an opinion on the financial statements of a business in which he, his firm or a partner has a substantial interest." },
    { id: "audit-102", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "Without the client's consent, an auditor gives a competitor of his client details of the client's pricing that he learned during the audit. No law requires the disclosure. This is misconduct under:", options: ["Clause (2) of Part II of the First Schedule", "Clause (6) of Part I of the First Schedule", "Clause (9) of Part I of the Second Schedule", "Clause (1) of Part I of the Second Schedule"], answer: 3, explanation: "Clause (1) of Part I of the Second Schedule covers a member in practice disclosing a client's information without consent, unless required by law." },
    { id: "audit-103", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA in practice receives ₹5 lakh from a client to pay the client's taxes and keeps it in his personal savings account until payment. This is misconduct under:", options: ["Clause (10) of Part I of the Second Schedule", "Clause (2) of Part I of the Second Schedule", "Clause (11) of Part I of the First Schedule", "Clause (3) of Part I of the First Schedule"], answer: 0, explanation: "Clause (10) of Part I of the Second Schedule makes it misconduct to fail to keep client money in a separate bank account or to fail to use it for its purpose within a reasonable time." },
    { id: "audit-104", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "During his absence, a CA in practice authorises his office manager, who is not a member of ICAI, to sign turnover certificates on his behalf. This is misconduct under:", options: ["Clause (1) of Part I of the First Schedule", "Clause (2) of Part I of the Second Schedule", "Clause (12) of Part I of the First Schedule", "Clause (5) of Part I of the First Schedule"], answer: 2, explanation: "Clause (12) of Part I of the First Schedule covers allowing a person who is not a member in practice to sign on the member's behalf." },
    { id: "audit-105", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA in practice, without the Council's permission, starts a business trading in electronic goods alongside his practice. This is misconduct under:", options: ["Clause (7) of Part I of the First Schedule", "Clause (11) of Part I of the First Schedule", "Clause (2) of Part IV of the First Schedule", "Clause (1) of Part II of the Second Schedule"], answer: 1, explanation: "Clause (11) of Part I of the First Schedule covers a member in practice engaging in any business or occupation other than the profession without the Council's permission." },
    { id: "audit-106", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA in practice pays a 10% commission on the audit fee to a retired bank manager, who is not a member of ICAI, for introducing a new audit client. This is misconduct under:", options: ["Clause (3) of Part I of the First Schedule", "Clause (6) of Part I of the First Schedule", "Clause (2) of Part IV of the First Schedule", "Clause (2) of Part I of the First Schedule"], answer: 3, explanation: "Clause (2) bars paying any share, commission or brokerage in fees to anyone other than a member, partner or retired partner; clause (3) is the reverse, accepting a non-member's profits." },
    { id: "audit-107", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "A CA signs an audit report on a company's financial statements when the entire examination was done by a cost accountant who is neither his partner nor his employee, and the CA did no work himself. This is misconduct under:", options: ["Clause (12) of Part I of the First Schedule", "Clause (4) of Part I of the Second Schedule", "Clause (2) of Part I of the Second Schedule", "Clause (3) of Part I of the Second Schedule"], answer: 2, explanation: "Clause (2) of Part I of the Second Schedule bars certifying a report unless the examination was made by the member, his partner or employee, or another CA in practice." },
    { id: "audit-108", chapter: "19. Professional Ethics & Liabilities of Auditors", prompt: "NFRA finds an audit firm guilty of professional misconduct in a listed company audit. Under s.132(4), the maximum debarment it can impose on the firm is:", options: ["10 years", "3 years", "Permanent debarment", "6 months"], answer: 0, explanation: "Under s.132(4)(c), NFRA may debar a member or firm for at least six months and up to ten years." }
  ]
};
export default bank;
